#### using a stack

```cpp
#include <string>
#include <vector>

int nestingScore(std::string str) {
  std::vector<int> stack { 0 };
  for (char ch : str) {
    if (ch == '[') {
      stack.push_back(0);
    } else {
      int popped = stack[stack.size() - 1];
      stack.pop_back();
      if (popped == 0) {
        stack[stack.size() - 1] += 1;
      } else {
        stack[stack.size() - 1] += popped * 2;
      }
    }
  }
  return stack[0];
}
```

- n = length of string
- Time: O(n)
- Space: O(n)
